import hashlib
import sys

# Known-bad SHA-256 hashes (in real life: millions, updated hourly)
KNOWN_BAD = {
    "275a021bbfb6489e54d471899f7db9d1663fc695ec2fe2a2c4538aabf651fd0f",  # EICAR test file
}

def sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(65536), b""):
            h.update(chunk)
    return h.hexdigest()

digest = sha256(sys.argv[1])
print("MATCH: quarantine" if digest in KNOWN_BAD else "No signature match", digest)
